fs.writeFileSync(p,JSON.stringify(d,null,2)+'\\n');
const negative=structuredClone(d);negative.suite={id:'s_arithmetic_negative_control',name:'Arithmetic wrong-answer control'};negative.cases[0].steps[1].assertion.needle='{\"sum\": 999}';
