JS
npx mcpjam cloud eval run --file .mcpjam/evals/arithmetic.json --project project_fixture --wait --wait-timeout 30000 --out artifacts/eval-report.json --no-telemetry --format json > artifacts/run.json 2> artifacts/run.stderr
npx mcpjam cloud eval run --file .mcpjam/evals/negative-control.json --project project_fixture --wait --wait-timeout 30000 --out artifacts/negative-report.json --no-telemetry --format json > artifacts/negative-run.json 2> artifacts/negative-run.stderr
negative_exit="'$?
printf '"'Wrong-answer control exit: %s\\n' \""'$negative_exit"
cat artifacts/run.json
cat artifacts/negative-run.json'

